{
  "category_edits": [
    {
      "category": "learning_objective",
      "rationale": "Average the existing logistic loss within each sequence, then across sequences, giving short and long histories equal weight across all four datasets. Preserve sampling, architecture, inference and training settings.",
      "edits": [
        {
          "find": "    return (loss * mask).sum() / mask.sum().clamp(min=1.0)",
          "replace": "    sequence_loss = (loss * mask).sum(dim=1) / mask.sum(dim=1).clamp(min=1.0)\n    return sequence_loss.mean()"
        }
      ]
    }
  ],
  "change_summary": "Change only loss reduction to equal-sequence weighting. Predictor and checkpoint shapes remain compatible; retain one NextItNet model per dataset."
}
